/* MCU backend: dataset is included as headers generated by
 * tools/prep_smatable.py. Fold + scheme are compile-time fixed via up to
 * four header slots — TRAIN and TEST are required, RETAIN and CALIB are
 * optional (leave undefined to bake a dataset without those splits, count
 * 0; schemes that don't define them, e.g. AOS / 80_20):
 *
 *   -DSMATABLE_BAKED_TRAIN_HEADER="<path-or-name>.h"
 *   -DSMATABLE_BAKED_RETAIN_HEADER="<path-or-name>.h"   (optional)
 *   -DSMATABLE_BAKED_CALIB_HEADER="<path-or-name>.h"    (optional)
 *   -DSMATABLE_BAKED_TEST_HEADER="<path-or-name>.h"
 *
 * Defaults below match the synthetic test fixture
 * data/smatable/folds/LOSO/fold_00_*.h so the file builds out of the box
 * once prep_smatable.py has been run.
 *
 * Each #include'd header defines its own
 *   SMATABLE_BAKED_N_SAMPLES / N_CHANNELS / WINDOW_SAMPLES / N_CLASSES
 * but per the prep guarantee they agree on the layout constants — only
 * SMATABLE_BAKED_N_SAMPLES differs across splits. Layout agreement across
 * splits is checked at compile time via _Static_assert. All headers expose
 * the same symbol names (`smatable_baked_x_bits`, `smatable_baked_y`); we
 * dodge the name clash by `#define`-renaming those symbols before each
 * include and `#undef`-ing all eight SMATABLE_BAKED_* macros afterwards
 * (the generated headers define them without include guards).
 */

#define SOURCE_FILE "SMATABLE_DATASET_BAKED"

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "smatable_dataset.h"

/* Symbol-suffix machinery so this backend can co-exist with the npy backend
 * inside the L1 equivalence test (tests/dataset_backend_equiv.c). Normal
 * single-backend builds leave SMATABLE_FN_SUFFIX undefined. */
#ifndef SMATABLE_FN_SUFFIX
# define SMATABLE_FN_SUFFIX
#endif
#define _SMA_CAT_INNER(a, b) a##b
#define _SMA_CAT(a, b) _SMA_CAT_INNER(a, b)
#define SMA(name) _SMA_CAT(name, SMATABLE_FN_SUFFIX)

#ifndef SMATABLE_BAKED_TRAIN_HEADER
#define SMATABLE_BAKED_TRAIN_HEADER "smatable/folds/LOSO/fold_00_train.h"
#endif
#ifndef SMATABLE_BAKED_TEST_HEADER
#define SMATABLE_BAKED_TEST_HEADER "smatable/folds/LOSO/fold_00_test.h"
#endif
/* SMATABLE_BAKED_RETAIN_HEADER / SMATABLE_BAKED_CALIB_HEADER are optional:
 * leave them undefined to bake a dataset without those splits (count 0). */

/* --- train: defines the layout every other split must match ------------ */
#include SMATABLE_BAKED_TRAIN_HEADER
enum {
    BAKED_TRAIN_N = SMATABLE_BAKED_N_SAMPLES,
    BAKED_N_CHANNELS = SMATABLE_BAKED_N_CHANNELS,
    BAKED_WINDOW_SAMPLES = SMATABLE_BAKED_WINDOW_SAMPLES,
    BAKED_N_CLASSES = SMATABLE_BAKED_N_CLASSES,
    BAKED_FLOATS_PER_SAMPLE_T = SMATABLE_BAKED_FLOATS_PER_SAMPLE,
};
static const uint32_t *const baked_train_x_bits = smatable_baked_x_bits;
static const int32_t *const baked_train_y = smatable_baked_y;
#undef SMATABLE_BAKED_FOLD
#undef SMATABLE_BAKED_SCHEME
#undef SMATABLE_BAKED_SPLIT
#undef SMATABLE_BAKED_N_SAMPLES
#undef SMATABLE_BAKED_N_CHANNELS
#undef SMATABLE_BAKED_WINDOW_SAMPLES
#undef SMATABLE_BAKED_N_CLASSES
#undef SMATABLE_BAKED_FLOATS_PER_SAMPLE

/* --- retain (optional) --------------------------------------------------- */
#ifdef SMATABLE_BAKED_RETAIN_HEADER
#define smatable_baked_x_bits smatable_baked_x_bits_retain
#define smatable_baked_y smatable_baked_y_retain
#include SMATABLE_BAKED_RETAIN_HEADER
enum {
    BAKED_RETAIN_N = SMATABLE_BAKED_N_SAMPLES,
    BAKED_RETAIN_C = SMATABLE_BAKED_N_CHANNELS,
    BAKED_RETAIN_T = SMATABLE_BAKED_WINDOW_SAMPLES,
};
static const uint32_t *const baked_retain_x_bits = smatable_baked_x_bits_retain;
static const int32_t *const baked_retain_y = smatable_baked_y_retain;
#undef smatable_baked_x_bits
#undef smatable_baked_y
#undef SMATABLE_BAKED_FOLD
#undef SMATABLE_BAKED_SCHEME
#undef SMATABLE_BAKED_SPLIT
#undef SMATABLE_BAKED_N_SAMPLES
#undef SMATABLE_BAKED_N_CHANNELS
#undef SMATABLE_BAKED_WINDOW_SAMPLES
#undef SMATABLE_BAKED_N_CLASSES
#undef SMATABLE_BAKED_FLOATS_PER_SAMPLE
#else
enum { BAKED_RETAIN_N = 0, BAKED_RETAIN_C = BAKED_N_CHANNELS, BAKED_RETAIN_T = BAKED_WINDOW_SAMPLES };
static const uint32_t *const baked_retain_x_bits = NULL;
static const int32_t *const baked_retain_y = NULL;
#endif

/* --- calib (optional) ---------------------------------------------------- */
#ifdef SMATABLE_BAKED_CALIB_HEADER
#define smatable_baked_x_bits smatable_baked_x_bits_calib
#define smatable_baked_y smatable_baked_y_calib
#include SMATABLE_BAKED_CALIB_HEADER
enum {
    BAKED_CALIB_N = SMATABLE_BAKED_N_SAMPLES,
    BAKED_CALIB_C = SMATABLE_BAKED_N_CHANNELS,
    BAKED_CALIB_T = SMATABLE_BAKED_WINDOW_SAMPLES,
};
static const uint32_t *const baked_calib_x_bits = smatable_baked_x_bits_calib;
static const int32_t *const baked_calib_y = smatable_baked_y_calib;
#undef smatable_baked_x_bits
#undef smatable_baked_y
#undef SMATABLE_BAKED_FOLD
#undef SMATABLE_BAKED_SCHEME
#undef SMATABLE_BAKED_SPLIT
#undef SMATABLE_BAKED_N_SAMPLES
#undef SMATABLE_BAKED_N_CHANNELS
#undef SMATABLE_BAKED_WINDOW_SAMPLES
#undef SMATABLE_BAKED_N_CLASSES
#undef SMATABLE_BAKED_FLOATS_PER_SAMPLE
#else
enum { BAKED_CALIB_N = 0, BAKED_CALIB_C = BAKED_N_CHANNELS, BAKED_CALIB_T = BAKED_WINDOW_SAMPLES };
static const uint32_t *const baked_calib_x_bits = NULL;
static const int32_t *const baked_calib_y = NULL;
#endif

/* --- test ---------------------------------------------------------------- */
#define smatable_baked_x_bits smatable_baked_x_bits_test
#define smatable_baked_y smatable_baked_y_test
#include SMATABLE_BAKED_TEST_HEADER
enum {
    BAKED_TEST_N = SMATABLE_BAKED_N_SAMPLES,
    BAKED_TEST_C = SMATABLE_BAKED_N_CHANNELS,
    BAKED_TEST_T = SMATABLE_BAKED_WINDOW_SAMPLES,
};
static const uint32_t *const baked_test_x_bits = smatable_baked_x_bits_test;
static const int32_t *const baked_test_y = smatable_baked_y_test;
#undef smatable_baked_x_bits
#undef smatable_baked_y

_Static_assert(BAKED_RETAIN_C == BAKED_N_CHANNELS && BAKED_CALIB_C == BAKED_N_CHANNELS &&
                   BAKED_TEST_C == BAKED_N_CHANNELS,
               "baked split headers disagree on channel count");
_Static_assert(BAKED_RETAIN_T == BAKED_WINDOW_SAMPLES && BAKED_CALIB_T == BAKED_WINDOW_SAMPLES &&
                   BAKED_TEST_T == BAKED_WINDOW_SAMPLES,
               "baked split headers disagree on window length");

/* --- backend ------------------------------------------------------------ */

struct smatable_dataset {
    int dummy; /* singleton sentinel — all data is in static const tables */
};

static smatable_dataset_t SINGLETON;

static inline float as_f32(uint32_t u) {
    /* L0 reconstruction: the 4 bytes the C compiler stored equal the bytes
     * numpy wrote into the .npy. */
    union { uint32_t u; float f; } v;
    v.u = u;
    return v.f;
}

smatable_dataset_t *SMA(smatableDatasetOpen)(void) { return &SINGLETON; }

void SMA(smatableDatasetClose)(smatable_dataset_t *ds) { (void)ds; }

size_t SMA(smatableDatasetNChannels)    (const smatable_dataset_t *ds) { (void)ds; return BAKED_N_CHANNELS;     }
size_t SMA(smatableDatasetWindowSamples)(const smatable_dataset_t *ds) { (void)ds; return BAKED_WINDOW_SAMPLES; }
size_t SMA(smatableDatasetWindowFloats) (const smatable_dataset_t *ds) { (void)ds; return BAKED_FLOATS_PER_SAMPLE_T; }
size_t SMA(smatableDatasetNClasses)     (const smatable_dataset_t *ds) { (void)ds; return BAKED_N_CLASSES;      }

static void copyOne(const uint32_t *src, size_t i, float *outX) {
    const uint32_t *row = src + i * (size_t)BAKED_FLOATS_PER_SAMPLE_T;
    for (size_t j = 0; j < (size_t)BAKED_FLOATS_PER_SAMPLE_T; j++) {
        outX[j] = as_f32(row[j]);
    }
}

static size_t splitN(smatable_split_t s) {
    switch (s) {
    case SMATABLE_SPLIT_TRAIN: return BAKED_TRAIN_N;
    case SMATABLE_SPLIT_RETAIN: return BAKED_RETAIN_N;
    case SMATABLE_SPLIT_CALIB: return BAKED_CALIB_N;
    case SMATABLE_SPLIT_TEST: return BAKED_TEST_N;
    default: return 0;
    }
}
static const uint32_t *splitX(smatable_split_t s) {
    switch (s) {
    case SMATABLE_SPLIT_TRAIN: return baked_train_x_bits;
    case SMATABLE_SPLIT_RETAIN: return baked_retain_x_bits;
    case SMATABLE_SPLIT_CALIB: return baked_calib_x_bits;
    case SMATABLE_SPLIT_TEST: return baked_test_x_bits;
    default: return NULL;
    }
}
static const int32_t *splitY(smatable_split_t s) {
    switch (s) {
    case SMATABLE_SPLIT_TRAIN: return baked_train_y;
    case SMATABLE_SPLIT_RETAIN: return baked_retain_y;
    case SMATABLE_SPLIT_CALIB: return baked_calib_y;
    case SMATABLE_SPLIT_TEST: return baked_test_y;
    default: return NULL;
    }
}
static void checkSplit(smatable_split_t split) {
    if ((int)split < 0 || split >= SMATABLE_SPLIT_COUNT) {
        fprintf(stderr, "[SMATABLE_DATASET_BAKED] bad split id %d\n", (int)split);
        exit(1);
    }
}

size_t SMA(smatableDatasetSplitCount)(const smatable_dataset_t *ds, smatable_split_t split) {
    (void)ds;
    checkSplit(split);
    return splitN(split);
}

void SMA(smatableDatasetGetSplit)(const smatable_dataset_t *ds, smatable_split_t split, size_t i,
                                  float *outX, int32_t *outY) {
    (void)ds;
    checkSplit(split);
    const uint32_t *x = splitX(split);
    if (x == NULL || i >= splitN(split)) {
        fprintf(stderr, "[SMATABLE_DATASET_BAKED] %s index %zu out of range (count=%zu)\n",
                smatableSplitName(split), i, splitN(split));
        exit(1);
    }
    copyOne(x, i, outX);
    *outY = splitY(split)[i];
}

size_t SMA(smatableDatasetTrainCount)(const smatable_dataset_t *ds) { (void)ds; return BAKED_TRAIN_N; }
size_t SMA(smatableDatasetTestCount)(const smatable_dataset_t *ds) { (void)ds; return BAKED_TEST_N; }
void SMA(smatableDatasetGetTrain)(const smatable_dataset_t *ds, size_t i, float *outX, int32_t *outY) {
    SMA(smatableDatasetGetSplit)(ds, SMATABLE_SPLIT_TRAIN, i, outX, outY);
}
void SMA(smatableDatasetGetTest)(const smatable_dataset_t *ds, size_t i, float *outX, int32_t *outY) {
    SMA(smatableDatasetGetSplit)(ds, SMATABLE_SPLIT_TEST, i, outX, outY);
}
